import{_ as t,a as r,c as a,ac as d}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"程序员英语 02：技术词汇与句子骨架","description":"用搭配、上下文和主谓宾结构理解常见技术英语，避免逐词翻译和容易混淆的术语。","frontmatter":{"title":"程序员英语 02：技术词汇与句子骨架","description":"用搭配、上下文和主谓宾结构理解常见技术英语，避免逐词翻译和容易混淆的术语。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"程序员英语","summary":"用搭配、上下文和主谓宾结构理解常见技术英语，避免逐词翻译和容易混淆的术语。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview"},"next":{"text":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview"},"next":{"text":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs"}},"headers":[],"relativePath":"life/english/programmer/vocabulary.md","filePath":"life/english/programmer/vocabulary.md"}'),o={name:"life/english/programmer/vocabulary.md"};function i(l,e,s,n,c,h){return r(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="程序员英语-02-技术词汇与句子骨架" tabindex="-1">程序员英语 02：技术词汇与句子骨架 <a class="header-anchor" href="#程序员英语-02-技术词汇与句子骨架" aria-label="Permalink to &quot;程序员英语 02：技术词汇与句子骨架&quot;">​</a></h1><p>遇到 <code>The worker drains the queue before shutdown.</code>，逐词查到“工人、排水、队伍”并不能帮助理解。开发语境中的意思是：工作线程或进程在关闭前处理完队列里的待处理项。先确认对象和动作，再确定词义。</p><h2 id="把词汇放进动作里" tabindex="-1">把词汇放进动作里 <a class="header-anchor" href="#把词汇放进动作里" aria-label="Permalink to &quot;把词汇放进动作里&quot;">​</a></h2><table tabindex="0"><thead><tr><th>搭配</th><th>在开发中的常见含义</th><th>原创例句</th></tr></thead><tbody><tr><td>parse a file</td><td>按格式解析文件</td><td>The parser rejects incomplete records.</td></tr><tr><td>validate input</td><td>校验输入</td><td>Validate the length before saving the value.</td></tr><tr><td>allocate memory</td><td>分配内存</td><td>The buffer allocates memory on demand.</td></tr><tr><td>release a lock</td><td>释放锁</td><td>Release the lock before running the callback.</td></tr><tr><td>handle an error</td><td>处理错误</td><td>The caller handles missing files.</td></tr><tr><td>raise an exception</td><td>抛出异常</td><td>The loader raises an exception for invalid syntax.</td></tr><tr><td>resolve a dependency</td><td>解析或确定依赖</td><td>The build tool resolves dependencies before compilation.</td></tr><tr><td>persist a change</td><td>持久化修改</td><td>The editor persists changes when you save.</td></tr><tr><td>retry an operation</td><td>重试操作</td><td>Retry the operation after checking the cause.</td></tr><tr><td>reproduce a failure</td><td>复现失败</td><td>I can reproduce the failure with this input.</td></tr><tr><td>backward compatible</td><td>向后兼容</td><td>The new reader is backward compatible with version 2 files.</td></tr><tr><td>deprecated</td><td>已不推荐使用</td><td>This option is deprecated but still accepted in this version.</td></tr></tbody></table><p>同一个词随上下文改变含义：<code>resolve a dependency</code> 与 <code>resolve an issue</code> 的对象不同；<code>argument</code> 在函数调用里通常是实参，在讨论中可能是论点。词汇卡应记录完整搭配，避免只写一个中文对应词。</p><p><code>deprecated</code> 不等于已经删除，<code>removed</code> 才表示移除；<code>concurrent</code> 强调任务在时间上交错推进，<code>parallel</code> 强调同时执行。读到这些词后，还要找版本与执行模型，不能只凭词表推断具体产品行为。</p><h2 id="先找句子主干-再加限定" tabindex="-1">先找句子主干，再加限定 <a class="header-anchor" href="#先找句子主干-再加限定" aria-label="Permalink to &quot;先找句子主干，再加限定&quot;">​</a></h2><p>看这句原创说明：</p><blockquote><p>The cache stores values that are expensive to compute until they expire.</p></blockquote><p>先抽出主干：<code>The cache / stores / values</code>，即缓存存储值。<code>that are expensive to compute</code> 修饰 values，说明是哪类值。<code>until they expire</code> 补充保留多久，<code>they</code> 指这些值。</p><p>按这个顺序阅读，比从左到右逐字翻译更容易保住整体含义：</p><ol><li>谁做事：cache。</li><li>做什么：stores。</li><li>对什么做：values。</li><li>哪些值、何时结束：计算成本高，直到过期。</li></ol><p>如果句子指代不清，不必猜作者意思。例如 <code>The worker passes the buffer to the parser after it starts.</code> 中 <code>it</code> 可能指 worker，也可能指 parser。写作时应直接重复名称。</p><h2 id="几组会改变实现的表达" tabindex="-1">几组会改变实现的表达 <a class="header-anchor" href="#几组会改变实现的表达" aria-label="Permalink to &quot;几组会改变实现的表达&quot;">​</a></h2><table tabindex="0"><thead><tr><th>表达</th><th>应保留的逻辑</th></tr></thead><tbody><tr><td>at least 3</td><td>不少于 3，包含 3</td></tr><tr><td>at most 3</td><td>不多于 3，包含 3</td></tr><tr><td>fewer than 3</td><td>少于 3，不包含 3</td></tr><tr><td>only if the file exists</td><td>文件存在是必要条件，不保证一定执行</td></tr><tr><td>unless the file exists</td><td>除非文件存在，否则执行所述行为</td></tr><tr><td>may fail</td><td>可能失败，不是在报告已失败</td></tr><tr><td>has failed</td><td>已经发生失败</td></tr></tbody></table><h2 id="练习-保留技术含义" tabindex="-1">练习：保留技术含义 <a class="header-anchor" href="#练习-保留技术含义" aria-label="Permalink to &quot;练习：保留技术含义&quot;">​</a></h2><ol><li>翻译 <code>The reader accepts at most 16 records unless strict mode is enabled.</code>，并指出不能确定的内容。</li><li>把 <code>The worker passes the buffer to the parser after it starts.</code> 改成明确表达“解析器启动后再传入”的句子。</li><li>说明 <code>The option is deprecated in version 4.</code> 能否证明第 4 版已经不接受该选项。</li></ol><details class="details custom-block"><summary>查看答案与讲解</summary><ol><li>未启用严格模式时，读取器最多接受 16 条记录。严格模式启用后接受多少条，原句没有说明；不要自行补成零条或无限条。</li><li><code>After the parser starts, the worker passes the buffer to it.</code> 这里 <code>it</code> 有清晰指向；也可直接重复 <code>the parser</code>。</li><li>不能。需要另查移除计划和当前版本行为。可以表述为 <code>The option is deprecated; check the migration guide for its replacement and removal schedule.</code></li></ol></details><h2 id="资料与延伸" tabindex="-1">资料与延伸 <a class="header-anchor" href="#资料与延伸" aria-label="Permalink to &quot;资料与延伸&quot;">​</a></h2><p><a href="https://developers.google.com/style/word-list" target="_blank" rel="noopener noreferrer">Google 开发者文档词汇表</a> 可用于核对特定术语与写作惯例。它是编辑风格参考，不是所有项目必须遵守的词典。团队已有术语时，优先保持同一文档内的一致性。</p>',20)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
